solution.solution.c:
#include <stdbool.h>
#include <stdint.h>

bool bit_is_set(uint32_t x, int n)
{
    return (x >> n) & 1u;
}

uint32_t set_bit(uint32_t x, int n)
{
    return x | (UINT32_C(1) << n);
}

uint32_t clear_bit(uint32_t x, int n)
{
    return x & ~(UINT32_C(1) << n);
}

uint32_t toggle_bit(uint32_t x, int n)
{
    return x ^ (UINT32_C(1) << n);
}

int count_bits(uint32_t x)
{
    int count = 0;
    while (x != 0) {
        x &= x - 1;          /* clears the lowest 1 bit */
        count++;
    }
    return count;
}

bool is_power_of_two(uint32_t x)
{
    return x != 0 && (x & (x - 1)) == 0;
}

uint32_t rotate_left(uint32_t x, int n)
{
    n &= 31;
    if (n == 0) return x;
    return (x << n) | (x >> (32 - n));
}

unitTests:
TEST("testing bits") { CHECK(bit_is_set(5, 0)); CHECK(!bit_is_set(5, 1)); CHECK(bit_is_set(5, 2)); CHECK(bit_is_set(0x80000000u, 31)); CHECK(!bit_is_set(0, 31)); }
TEST("setting, clearing and toggling") { CHECK_EQ(set_bit(0, 3), 8u); CHECK_EQ(set_bit(8, 3), 8u); CHECK_EQ(set_bit(0, 31), 0x80000000u); CHECK_EQ(clear_bit(15, 0), 14u); CHECK_EQ(clear_bit(14, 0), 14u); CHECK_EQ(clear_bit(0xFFFFFFFFu, 31), 0x7FFFFFFFu); CHECK_EQ(toggle_bit(5, 1), 7u); CHECK_EQ(toggle_bit(7, 1), 5u); }
TEST("counting bits") { CHECK_EQ(count_bits(0), 0); CHECK_EQ(count_bits(1), 1); CHECK_EQ(count_bits(255), 8); CHECK_EQ(count_bits(0xF0F0F0F0u), 16); CHECK_EQ(count_bits(0xFFFFFFFFu), 32); }
TEST("powers of two") { CHECK(is_power_of_two(1)); CHECK(is_power_of_two(64)); CHECK(is_power_of_two(0x80000000u)); CHECK(!is_power_of_two(0)); CHECK(!is_power_of_two(6)); CHECK(!is_power_of_two(0xFFFFFFFFu)); }
TEST("rotating") { CHECK_EQ(rotate_left(1, 1), 2u); CHECK_EQ(rotate_left(0x80000000u, 1), 1u); CHECK_EQ(rotate_left(0x12345678u, 8), 0x34567812u); CHECK_EQ(rotate_left(0xABCDu, 0), 0xABCDu); CHECK_EQ(rotate_left(0x12345678u, 32), 0x12345678u); }

